<?php get_header(); ?><main id="conteudo" class="shell section-block"><div class="section-heading"><h1><?php if(is_search()) printf('Resultados para: %s',esc_html(get_search_query())); elseif(is_archive()) the_archive_title(); else single_post_title(); ?></h1></div><?php if(have_posts()): ?><div class="latest-grid"><?php while(have_posts()):the_post(); ?><article class="text-story"><?php if(has_post_thumbnail())the_post_thumbnail('medium'); ?><span class="kicker"><?php echo esc_html(jnt_category()); ?></span><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),24)); ?></p></article><?php endwhile; ?></div><?php the_posts_pagination(); else: ?><p>Nenhuma publicação encontrada.</p><?php endif; ?></main><?php get_footer(); ?>